// ModelActionReset restores ModelAction's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ModelActionReset(value *ModelAction) {
	clear(value.Verb[:])
	value.VerbLength = 0
	for i := range value.Args {
		ModelArgReset(&value.Args[i])
	}
	value.ArgsCount = 0
	clear(value.Actor[:])
	value.ActorLength = 0
}

func ModelActionMeasureBody(value *ModelAction, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ModelActionSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ModelActionMeasure(value *ModelAction) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ModelActionSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ModelActionMeasureReason(value *ModelAction) (int64, error) {
	size := ModelActionMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
