// One plan per lineage entry, laid down from THE LOCK's bytes: nothing
// compiles on the load path (§5.8 row 3).
var ModelSeenFixedLineagePlans = tableFixedLineagePlans(ModelSeenFixedKnown, ModelSeenFixedLayout, ModelSeenFixedDst, ModelSeenFixedHash)

