// A FILE: form byte, seven reserved zeros, the LAYOUT HASH at 8, body at 16,
// then the layout behind its u32 length, then the records to the end of it.
func ModelStepResultFixedMeasure(count int64) int64 {
	return TableFixedHeaderBytes + 4 + int64(len(ModelStepResultFixedLayout)) + count*ModelStepResultFixedRecordBytes
}

// ModelStepResultFixedSave is the fixed form's writer: it returns the bytes written, or -1 for a
// buffer too short or a value outside its declared contract (§3.1); see FixedSaveReason.
func ModelStepResultFixedSave(values []ModelStepResult, buffer []byte) int64 {
	need := ModelStepResultFixedMeasure(int64(len(values)))
	if int64(len(buffer)) < need {
		return -1
	}
	for k := range values {
		if !ModelStepResultFixedCheckBody(&values[k]) {
			return -1
		}
	}
	clear(buffer[:TableFixedHeaderBytes])
	buffer[0] = TableFixedForm
	tableFixedPut64(buffer[TableFixedHashAt:], ModelStepResultFixedHash)
	tableFixedPut32(buffer[TableFixedHeaderBytes:], uint32(len(ModelStepResultFixedLayout)))
	copy(buffer[TableFixedHeaderBytes+4:], ModelStepResultFixedLayout)
	at := buffer[TableFixedHeaderBytes+4+len(ModelStepResultFixedLayout):]
	for k := range values {
		tableFixedPut64(at, ModelStepResultFixedHash)
		clear(at[8 : 8+ModelStepResultFixedBodyBytes])
		ModelStepResultFixedWriteBody(at[8:], &values[k])
		at = at[ModelStepResultFixedRecordBytes:]
	}
	return need
}

